import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"43、【夬】 乾下兌上","description":"周易闡真 - 43、【夬】 乾下兌上","frontmatter":{"title":"43、【夬】 乾下兌上","description":"周易闡真 - 43、【夬】 乾下兌上"},"headers":[],"relativePath":"classics/chanzhen/044.md","filePath":"classics/chanzhen/044.md"}'),s={name:"classics/chanzhen/044.md"};function n(c,p,i,o,l,h){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：夬，決也，剛決柔也。健而說，決而和。揚於王庭，柔乘五剛也。孚號有厲，其危乃光也。告自邑，不利即戎，所尚乃窮也。利有攸往，剛長乃終也。</p></blockquote><h1 id="_43、【夬】-乾下兌上" tabindex="-1">43、【夬】 乾下兌上 <a class="header-anchor" href="#_43、【夬】-乾下兌上" aria-label="Permalink to “43、【夬】 乾下兌上”">​</a></h1><p>初九：壯於前趾，往不勝，為咎。</p><p>九二：惕號，莫夜有戎，勿恤。</p><p>九三：壯於頁1副本，有兇。君子夬，夬獨行，遇雨若濡，有慍無咎。</p><p>九四：臀無膚其行，次且牽羊悔亡，聞言不信。</p><p>九五:莧陸夬夬，中行無咎。</p><p>上六：無號，終有兇。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：澤上於天，夬。君子以施祿及下，居德則忌。</p><p>夬者，決也。上兌澤，下乾天，是澤上於天也。澤之水氣上升於天，化而為雨，滋潤萬物，似乎天不自私，決澤下流，夬之象也。</p><p>君子有見於此，知天有澤而萬物生，上有澤而下民安。以是施祿及下，使人人皆霑其恩也。但施祿於下者，施其德也。施德不知德，則施之者廣，施之者真，亦如天之無物不覆，無物不生。所謂大德不德，與天為配。若知施德為德，是自居其德，其心有私，施祿不久，不為之德，此施祿者之所最忌也。故君子物我同觀，施德不望報，有德而不居，其德日大，其心日小，決去一切自滿自大之心，亦如澤在天上，降於地下，出於固然也。修道積功累行，行等等方便利人之事，如施祿於人也。但行方便利人之事，多無真心。或圖虛名，或圖利賄，或應故事，外似利人，內實不利，稍不如意，怨天尤人，此本無德而反居德，何得謂之利人哉?試觀天之施澤萬物，豈望萬物有報乎?不望萬物有報，是天有德而不居德。天且不居德，而況常人之德何可居之乎?凡利益於人者，能效天之不居德，而德未有不大者也。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>夬，古快反。莫，音暮。頁1副本，音魁。次，七私反。且，七餘反。莧，音現。</p><p>夬者，決去也。卦體一陰居於五陽之上，陽將純而陰將盡，卦德健而和，和以行健，健而不猛，均有以陽去陰之義，故謂夬。此以陽退陰之卦，承上損卦而來。損者，止其悅而不妄悅，所以進陽退陰，以正氣而退客氣也。客氣者，識神所招，欲退客氣，莫若先去識神。人自交於後天，識神用事，酒色迷真，財氣亂性，情慾俱發，思慮紛生，心君迷惑，習於性成，非一朝一夕之故，豈能斬然決去哉!不能斬然決去，必須從容行事，隨時下手，終必識滅。滅而元神復，人心化而道心全，重見本來乾元面目矣。但此識神為人心所戀，欲去識神，莫若先明其心。心若一明，則道心現，而識神易去，故夬揚於王庭也。</p><p>王庭者，心君所居之處，乃分辨邪正之地。心明邪正，則心不為識神所迷，易於去之。但識神用事已久，根深權大，非可冒然下手，必須急緩得法，方能濟事。</p><p>曰孚號者，真心實意，以聚正氣也。曰有厲者，戒慎恐懼，以防邪氣也。曰告自邑者，煉己也。曰不利即戎者，待時也。</p><p>既能聚正氣，又能防邪氣，更能煉己待時，萬緣俱空，只一識神，乘時而決之，未有不利者也。</p><p>卦德健而和，從容不迫，待時下手，其即決陰之妙訣乎?</p><p>初九，在決陰之初，獨剛不柔，冒然前進，是壯於前趾矣。前趾之壯，不但不能決陰，而反有以助陰，陽不勝陰，無咎而自致咎。此剛而不謹於決陰者也。</p><p>九二，剛而能柔，儆惕自號，戒備嚴密，雖莫夜有戎，已伺於未發之先矣。何憂恤之有?此剛而能緩於決陰者也。</p><p>九三，剛躁太過，急欲成功，壯氣現之於頁1副本，宜有兇道。幸其以正去邪，為君子夬夬之決，但嫌其獨剛不柔，其行遇雨，若濡不能遽遂其志而有慍。然行既遇濡，始雖不能剛決，終必和決之，亦可無壯 頁1副本 之咎矣。此剛而速於決陰者也。</p><p>九四，剛居不正，道心為人心所累，如臀無膚，其行次且而決陰不果。幸其道心未泯，能以牽引陽氣而增長，本有悔而悔可亡。但嫌其不信決陰之言，道心中猶雜人心耳。此剛為柔傷，不知決陰者也。</p><p>九五，切近上陰，陰尊陽卑，道心為人心所瞞，貪戀識神，或決或不決，如莧陸夬夬，一時不能決斷其根然。</p><p>夫道心人心所爭者，毫髮之間，這邊是道心，那邊是人心，果於決陰，便是道心，不果於決陰，便是人心。心者，神之室，識神與人心相連，故夬夬不定。幸其陽將純、陰將盡之時，理終勝欲，雖決之不能自然，亦必勉強而能決，是以中於行，而可無咎。此剛為柔牽，勉強決陰者也。</p><p>上六，在決之終，群陰退盡，只有識神一陰未消，其時當決，其勢必滅，陽氣一進，陰氣即化，是以無號終有兇。陰氣之無號，即陽氣之孚號；陰氣之終兇，即陽氣之終吉。此陽氣純全、陰氣悉化之決者也。</p><p>然則決陰之道，不可太剛，不可太柔，必須剛中有柔，柔中有剛，漸次而決，進一分陽，退一分陰，陽氣進全，陰氣自化。若不知急緩運用，速欲成功，反助陰氣，有傷陽氣，陰氣終不能退，故退陰之道，須要深明火候耳。</p>',27)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
